import json,base64,cv2,numpy as np,sys,hashlib
p=sys.argv[1];d=json.load(open(p));raw=np.frombuffer(base64.b64decode(d['rgba_base64']),dtype=np.uint8).reshape(d['height'],d['width'],4);rgb=np.ascontiguousarray(raw[:,:,:3]);png=base64.b64decode(d['png_base64']);dec=cv2.cvtColor(cv2.imdecode(np.frombuffer(png,dtype=np.uint8),cv2.IMREAD_COLOR),cv2.COLOR_BGR2RGB);out={'source_pts_ms':d['source_pts_ms'],'width':d['width'],'height':d['height'],'rgb_bytes':int(rgb.size),'differing_channels':int(np.count_nonzero(rgb!=dec)),'max_absolute_difference':int(np.abs(rgb.astype('int16')-dec.astype('int16')).max()),'alpha_min':int(raw[:,:,3].min()),'alpha_max':int(raw[:,:,3].max()),'rgba_rgb_sha256':hashlib.sha256(rgb.tobytes()).hexdigest(),'png_decoded_rgb_sha256':hashlib.sha256(dec.tobytes()).hexdigest()};print(json.dumps(out,indent=2));assert out['differing_channels']==0
